// propKind is the kind a name=value escape's name spells, "" for none.
func propKind(name string) string {
	switch name {
	case "General_Category", "gc":
		return "gc"
	case "Script", "sc":
		return "sc"
	case "Script_Extensions", "scx":
		return "scx"
	}
	return ""
}
